sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  try {
    var result;
    var __result = (function() {
      var out = {};
      function ins(table, vals) {
        var gr = new GlideRecord(table); gr.initialize();
        for (var k in vals) gr.setValue(k, vals[k]);
        return gr.insert();
      }
      function findOrNull(table, q) { var gr = new GlideRecord(table); gr.addEncodedQuery(q); gr.query(); return gr.next() ? gr.getUniqueValue() : null; }

      var FACT = 'sn_gsm_government_service_case';
      // 1. Indicator source
      var cube = findOrNull('pa_cubes', 'name=DPM: Cases.New');
      if (!cube) cube = ins('pa_cubes', { name: 'DPM: Cases.New', facts_table: FACT, frequency: '10', calendar: 'standard',
        conditions: 'opened_atONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()^EQ' });
      out.cube = cube;

      // 2. Indicator (mirrors DPM: Number of new requests)
      var ind = findOrNull('pa_indicators', 'name=DPM: Number of new cases');
      if (!ind) ind = ins('pa_indicators', { name: 'DPM: Number of new cases', type: '1', cube: cube, aggregate: '1', frequency: '10',
        unit: '17b365e2d7320100ba986f14ce6103ad', direction: '2', precision: '1', collect_records: 'true', collect_breakdown_matrix: 'true',
        description: 'Number of government service cases with an opened date (opened_at) on collection date. Counts PSDS cases created by record producers, which do not create sc_request records.' });
      out.indicator = ind;

      // 3. Breakdown mapping scripts
      var hier = "var getHierarchy = function(seed, parentField, tableName) { var h = []; while (seed) { h.push(seed.toString()); var g = new GlideRecord(tableName); if (g.get(seed)) { seed = g.getValue(parentField); } else { seed = null; } if (new ArrayUtil().contains(h, seed)) break; if (g.getValue(parentField) == g.getValue('sys_id')) break; } return h; };\n";
      var svcFn = "function caseService() { var s = current.getValue('business_service'); if (!gs.nil(s)) return s; if (!gs.nil(current.getValue('service_offering'))) return current.service_offering.parent.toString(); return null; }\n";
      var scripts = {
        'DPM: Service Offerings': { name: 'Case by Service Offering', script: "function caseOffering() { var o = current.getValue('service_offering'); return gs.nil(o) ? null : o; }\ncaseOffering();" },
        'DPM: Services': { name: 'Case by Service', script: svcFn + "caseService();" },
        'DPM: Service Portfolios': { name: 'Case by Service Portfolio', script: svcFn + "function casePortfolio() { var s = caseService(); if (gs.nil(s)) return null; var g = new GlideRecord('cmdb_ci_service'); if (g.get(s) && !gs.nil(g.getValue('spm_service_portfolio'))) return g.getValue('spm_service_portfolio'); return null; }\ncasePortfolio();" },
        'DPM: Taxonomy Nodes': { name: 'Case by Taxonomy Node', script: svcFn + hier + "function caseTaxonomy() { var s = caseService(); if (gs.nil(s)) return null; var g = new GlideRecord('cmdb_ci_service'); if (!g.get(s)) return null; return getHierarchy(g.getValue('spm_taxonomy_node'), 'parent', 'spm_taxonomy_node'); }\ncaseTaxonomy();" }
      };
      out.mappings = [];
      for (var bdName in scripts) {
        var bd = findOrNull('pa_breakdowns', 'name=' + bdName);
        if (!bd) { out.mappings.push(bdName + ': breakdown not found'); continue; }
        var sc = findOrNull('pa_scripts', 'name=' + scripts[bdName].name + '^table=' + FACT);
        if (!sc) sc = ins('pa_scripts', { name: scripts[bdName].name, table: FACT, script: scripts[bdName].script });
        var bm = findOrNull('pa_breakdown_mappings', 'breakdown=' + bd + '^facts_table=' + FACT);
        if (!bm) bm = ins('pa_breakdown_mappings', { breakdown: bd, facts_table: FACT, scripted: 'true', script: sc });
        var ib = findOrNull('pa_indicator_breakdowns', 'indicator=' + ind + '^breakdown=' + bd);
        if (!ib) ib = ins('pa_indicator_breakdowns', { indicator: ind, breakdown: bd });
        out.mappings.push(bdName + ' -> script ' + sc + ', mapping ' + bm + ', ind_bd ' + ib);
      }

      // 4. Add to DPM daily collection job
      var daily = '1cc03b7a7770211051d2308eec5a9976';
      if (!findOrNull('pa_job_indicators', 'job=' + daily + '^indicator=' + ind)) ins('pa_job_indicators', { job: daily, indicator: ind });
      out.daily_job = 'added';
      JSON.stringify(out);
      ; if (typeof result !== 'undefined') return result;
    })();
    response.setBody({ success: true, result: (__result === undefined ? null : __result) });
  } catch(e) {
    response.setBody({ success: false, error: e + '', message: e.message || (e + '') });
  }
})(request, response);
